window.docContents[204].resolve({"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Arrays":{"contents":"An SMT array is total, so its Lean counterpart is Cvc.TotalMap ι κ: a default element plus the\nindices that differ from it. Constant arrays need cvc5's arrays-exp option.\n\nabbrev IntArray := TotalMap Int Int\n\n#eval Env.runIO do\n  let solver ← Solver.new\n  solver.setOption \"produce-models\" \"true\"\n  solver.setOption \"arrays-exp\" \"true\"\n  let a ← solver.declareConstAs IntArray \"a\"\n  let zero ← Term.mkInt 0\n  let zeros : Term IntArray ←\n    Term.mkConstArray zero\n  let three ← Term.mkInt 3\n\n  -- `a` is all zeros, except perhaps at index 3...\n  let forceZeroAt3 ← a.store three zero\n  smt! forceZeroAt3 = zeros >>= solver.assert\n  -- ...where it is `17`\n  let at3 ← a.select three\n  smt! at3 = 17 >>= solver.assert\n  solver.checkSat (ifSat := do\n    println! \"a := {← solver.getValue a}\")\n\n  -- reading back what was just written succeeds\n  let i ← solver.declareConstAs Int \"i\"\n  let v ← solver.declareConstAs Int \"v\"\n  let read ← (← a.store i v).select i\n  solver.checkSat (assuming := #[← smt! ¬ (read = v)])\n    (ifUnsat := println! \"{read} = {v}\")\n\n\na := { 3 ↦ 17, _ ↦ 0 }\n(select (store a i v) i) = v\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Overview","header":"1.10. Arrays","id":"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Arrays"}});